using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class AEFrameCopies {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../..")),h=r+"/SourceAssets/F1_AbandonedCamouflage/",e="Assets/Afrer_Seconds/05.Model/Environment/1F/";var plan=JObject.Parse(File.ReadAllText(h+"geometry_verified/Level_1F_Factory.json"));var manifest=JObject.Parse(File.ReadAllText(h+"models_environment.json"));var result=new List<object>();foreach(string id in new[]{"C04","VA","VB","VL"}){var old=GameObject.Find("F1_"+id+"_Frames");if(!old)continue;string from=e+"F1_"+id+"_Frames.fbx",to=e+"AE_"+id+"_Frames.fbx";if(!AssetDatabase.CopyAsset(from,to))throw new Exception("Copy failed "+to);var importer=(ModelImporter)AssetImporter.GetAtPath(to);var source=AssetDatabase.LoadAssetAtPath<GameObject>(from).GetComponentsInChildren<Renderer>().First().sharedMaterials;var target=old.GetComponentsInChildren<Renderer>().First().sharedMaterials;for(int i=0;i<source.Length;i++)importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),source[i].name),target[i]);importer.isReadable=false;importer.SaveAndReimport();var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(to),old.transform.parent);g.name="AE_"+id+"_Frames";g.transform.SetPositionAndRotation(old.transform.position,old.transform.rotation);g.transform.localScale=old.transform.localScale;
  var mesh=g.GetComponentInChildren<MeshFilter>().sharedMesh;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(mesh,out string guid,out long local);string key=guid+"_"+local;foreach(var row in plan["rows"].Where(row=>(string)row["asset"]==from)){row["asset"]=to;row["mesh"]=key;}
  foreach(var mf in g.GetComponentsInChildren<MeshFilter>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;foreach(var rr in g.GetComponentsInChildren<Renderer>()){GameObjectUtility.SetStaticEditorFlags(rr.gameObject,StaticEditorFlags.OccludeeStatic|StaticEditorFlags.ReflectionProbeStatic);PrefabUtility.RecordPrefabInstancePropertyModifications(rr);}UnityEngine.Object.DestroyImmediate(old);manifest[id+"_Frames"]=JObject.FromObject(new{asset=to,category="Environment",triangles=new[]{mesh.triangles.Length/3},materials=target.Select(m=>m.name).ToArray(),origin="Scoped copy of first-pass 1F frame; original retained"});result.Add(new{from,to,key});}
  File.WriteAllText(h+"models_environment.json",manifest.ToString());File.WriteAllText(h+"geometry_verified/Level_1F_Factory.json",plan.ToString());File.WriteAllText(h+"frame_copies.json",JsonConvert.SerializeObject(result,Formatting.Indented));AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return result;
 }
}
